//! Snapshots generated by executing the checked-in TypeScript oracle, not by
//! copying Rust's own rendering. Normal tests need neither Node nor legacy/pi.

use std::sync::Arc;

use pi_plugin::{PluginDriver, RegistriesBuilder, Tool};
use pi_plugin_codemode::{CodemodeOptions, ConfiguredCodemodePlugin};
use serde_json::{Value, json};

use super::{BuildSystemPromptOptions, build_system_prompt, render_options};

fn fixture() -> Value {
    serde_json::from_str(include_str!("../../tests/fixtures/prompt-conformance.json")).unwrap()
}

#[test]
fn system_prompt_matches_current_pi_oracle() {
    for case in fixture()["prompts"].as_array().unwrap() {
        let mut options: BuildSystemPromptOptions =
            serde_json::from_value(case["options"].clone()).unwrap();
        options.readme_path = Some("/pi/README.md".into());
        options.docs_path = Some("/pi/docs".into());
        options.examples_path = Some("/pi/examples".into());
        let rendered = render_options(options.clone()).unwrap();
        assert_eq!(rendered.system_prompt, case["expected"].as_str().unwrap());
        assert_eq!(
            rendered.sections.is_none(),
            options.force_system_prompt.is_some()
        );
        assert_eq!(
            build_system_prompt(&options).unwrap(),
            case["expected"].as_str().unwrap(),
            "oracle scenario: {}",
            case["name"],
        );
    }
}

#[test]
fn tool_declarations_match_current_pi_oracle() {
    // The Coding product and oracle generator enable models explicitly. The
    // standalone codemode factory correctly leaves that optional facade absent.
    let mut builder = RegistriesBuilder::new();
    PluginDriver::new(vec![Arc::new(ConfiguredCodemodePlugin::new(
        CodemodeOptions {
            models: true,
            ..CodemodeOptions::default()
        },
    ))])
    .unwrap()
    .register_all(&mut builder)
    .unwrap();
    let codemode = builder.freeze().tool("codemode").unwrap();
    let specs = [
        pi_plugin_read::ReadTool.spec(),
        pi_plugin_bash::BashTool.spec(),
        pi_plugin_powershell::PowerShellTool.spec(),
        pi_plugin_edit::EditTool.spec(),
        pi_plugin_write::WriteTool.spec(),
        pi_plugin_grep::GrepTool.spec(),
        pi_plugin_find::FindTool.spec(),
        pi_plugin_ls::LsTool.spec(),
        codemode.spec(),
        pi_plugin_tool_search::tool_search_tool().spec(),
    ];
    let oracle = fixture();
    let expected = oracle["tools"].as_array().unwrap();
    assert_eq!(specs.len(), expected.len());
    let codemode_docs = pi_plugin_codemode::CodemodeOptions::default()
        .docs_path
        .to_string_lossy()
        .replace('\\', "/");
    for spec in specs {
        let actual = json!({
            "name": spec.name,
            "label": spec.label,
            "description": spec.description.replace(&codemode_docs, "/pi/docs/codemode.md"),
            "parameters": spec.parameters,
            "outputSchema": spec.output_schema,
            "constrainedSampling": spec.constrained_sampling,
            "promptSnippet": spec.prompt_snippet,
            "promptGuidelines": spec.prompt_guidelines,
        });
        let expected = expected
            .iter()
            .find(|entry| entry["name"] == spec.name)
            .unwrap();
        assert_eq!(&actual, expected, "oracle tool: {}", spec.name);
    }
}
